# ── 13 ──────────────────────────────────────────────────────────────────
stage "Verify every section App Store Connect requires"
say "One pass over the record, section by section. Answer honestly — the point of"
say "this stage is a list of what is still missing, not a clean sheet."
say ""
check "Name and subtitle" "App Information shows '$TITLE' and a subtitle of 30 characters or fewer."
check "Categories" "Primary Productivity, a secondary category set, Content Rights and the DSA trader question answered."
check "Privacy Policy URL" "$PRIVACY_URL is saved and opens the policy in a browser."
check "Age rating" "The questionnaire is complete, the rating reads 4+, and the Made for Kids choice matches this run ($MADE_FOR_KIDS)."
check "App Privacy" "All six data-type groups are answered, every one reads 'not used for tracking', and the section is PUBLISHED."
check "Privacy and policy agree" "The published labels say nothing the policy at $PRIVACY_URL does not."
check "Keywords" "The keyword field holds all 100 characters, with no space after any comma."
check "Description and URLs" "Description, promotional text, Copyright and a Support URL of $SUPPORT_URL are saved."
check "Subscription disclosures" "The Description states the subscription's length, price and renewal terms and links $TERMS_URL, and the EULA field is answered."
check "Pricing and Availability" "The price is Free, territories are chosen, and the version no longer reports it as missing."
check "Export compliance" "The version page does not ask for an encryption answer, because the build carries ITSAppUsesNonExemptEncryption."
check "App Review Information" "A working parent demo account, the Parent PIN, and how a child device joins are in the review notes."
check "Screenshots" "At least three 6.9-inch screenshots are uploaded and show the four core loops."
pause

# ── 14 ──────────────────────────────────────────────────────────────────
stage "Report back to issue #$ISSUE"
say "Posting the section-by-section result as a comment."
if (( ${#RESULTS[@]} == 0 )); then
  warn "Nothing recorded — nothing to report."
  SKIPPED+=("the verification comment on issue #$ISSUE")
  finish
  exit 0
fi
# shellcheck disable=SC2016  # the backticks are Markdown for the issue comment
comment=$(printf '## App Store Connect listing — verification\n\nRun via `scripts/setup-store-listing.sh` on %s.\nMade for Kids: **%s**.\n\n%s\n' \
  "$(date -u '+%Y-%m-%d %H:%M UTC')" "$MADE_FOR_KIDS" "$(printf '%s\n' "${RESULTS[@]}")")
printf '\n%s\n\n' "$comment"
if confirm "Post this to issue #$ISSUE?"; then
  if printf '%s' "$comment" | gh issue comment "$ISSUE" --body-file - >/dev/null 2>&1; then
    printf '  %s✓ posted%s to issue #%s\n' "$GREEN" "$RESET" "$ISSUE"
  else
    warn "gh could not post — copy the comment above onto the issue by hand."
    SKIPPED+=("the verification comment on issue #$ISSUE")
  fi
else
  SKIPPED+=("the verification comment on issue #$ISSUE")
fi
pause

finish
note "The build and the submission itself are #83, and it is blocked on this one."
printf '\n'
